class Solution {
    public int coinChange(int[] coins, int amount) {
        int INF = amount + 1;                       // 最多用 amount 枚，amount + 1 就相当于凑不出
        int[] dp = new int[amount + 1];             // dp[i]：凑出 i 最少几枚
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= amount; i++) {
            for (int c : coins) {
                if (c <= i && dp[i - c] + 1 < dp[i]) {
                    dp[i] = dp[i - c] + 1;          // 最后一枚用 c
                }
            }
        }
        return dp[amount] != INF ? dp[amount] : -1;
    }
}

